import React, { ReactNode, useState, useEffect, Children, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useAnimation } from './AnimationQueue';

interface AnimatedListProps {
  children: ReactNode;
  className?: string;
  staggerDelay?: number;
  onComplete?: () => void;
  component?: 'ul' | 'ol' | 'div';
  priority?: number;
  dependencies?: string[];
  name?: string; // Add name for dependency tracking
}

const DEBUG = false;

/**
 * Animated List component that renders children with staggered animations
 * Uses the animation queue system for coordinated animations
 */
const AnimatedList: React.FC<AnimatedListProps> = ({
  children,
  className = '',
  staggerDelay = 0.05,
  onComplete,
  component = 'ul',
  priority = 0,
  dependencies = [],
  name
}) => {
  const [activeItemIndex, setActiveItemIndex] = useState(-1);
  const [isComplete, setIsComplete] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);
  const [itemAnimationIds, setItemAnimationIds] = useState<string[]>([]);
  const animationIdRef = useRef<string | null>(null);

  // Get animation context
  const { registerAnimation, completeAnimation, getAnimationId } = useAnimation();

  // Filter out empty children
  const childArray = Children.toArray(children).filter(child => 
    child !== null && 
    (typeof child !== 'string' || child.trim() !== '')
  );

  // Register with animation queue on mount
  useEffect(() => {
    if (childArray.length === 0) return;

    // First, register this list as an animation
    const listId = registerAnimation('list', {
      priority,
      dependencies,
      onStart: () => {
        if (DEBUG) console.log(`Starting list animation: ${name || 'unnamed'}`);
        setActiveItemIndex(-1);
        setIsComplete(false);
        setIsAnimating(true);

        // Register each item animation with a dependency on the previous item
        const ids: string[] = [];

        childArray.forEach((_, index) => {
          // Each item depends on the list and the previous item (except first item)
          const itemDeps = index === 0 
            ? [listId] // First item only depends on the list
            : [ids[index - 1]]; // Other items depend on previous item

          const itemName = name ? `${name}-item-${index}` : undefined;
          const itemId = registerAnimation('list', {
            priority: priority - 1, // Lower priority than the list itself
            dependencies: itemDeps,
            name: itemName,
            onStart: () => {
              if (DEBUG) console.log(`Starting item animation: ${itemName || index}`);
              setActiveItemIndex(index);
            },
            onComplete: () => {
              if (DEBUG) console.log(`Completed item animation: ${itemName || index}`);
              // The last item completion will complete the list animation
              if (index === childArray.length - 1) {
                setIsComplete(true);
                setIsAnimating(false);
                if (animationIdRef.current) {
                  completeAnimation(animationIdRef.current);
                }
              }
            }
          });
          ids.push(itemId);
        });

        setItemAnimationIds(ids);
      },
      onComplete: () => {
        if (DEBUG) console.log(`Completed list animation: ${name || 'unnamed'}`);
        if (onComplete) {
          onComplete();
        }
      },
      name
    });

    animationIdRef.current = listId;

    // Clean up
    return () => {
      if (animationIdRef.current && isAnimating && !isComplete) {
        completeAnimation(animationIdRef.current);
      }
    };
  }, [
    childArray.length, 
    priority, 
    dependencies, 
    registerAnimation, 
    completeAnimation, 
    onComplete, 
    name, 
    isAnimating,
    isComplete,
    childArray
  ]);

  // Animation variants
  const itemVariants = {
    hidden: { opacity: 0, y: 2 },
    visible: { 
      opacity: 1, 
      y: 0, 
      transition: { 
        duration: 0.15,
        delay: staggerDelay // Apply stagger delay
      } 
    }
  };

  // Create component with proper tag
  const Component = component as any;

  // Render fallback content if needed
  if (!isAnimating && childArray.length > 0 && activeItemIndex === -1) {
    return (
      <Component 
        className={`animated-list ${className} fallback`}
        style={{
          padding: 0,
          margin: 0,
          listStyle: 'none',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start'
        }}
      >
        {childArray.map((child, index) => (
          <li
            key={index}
            style={{
              width: '100%',
              justifyContent: 'flex-start',
              listStyle: 'none'
            }}
          >
            {child}
          </li>
        ))}
      </Component>
    );
  }

  return (
    <Component 
      className={`animated-list ${className} ${isComplete ? 'complete' : ''}`}
      style={{
        padding: 0,
        margin: 0,
        listStyle: 'none',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'flex-start'
      }}
    >
      {childArray.map((child, index) => (
        <AnimatePresence key={index} mode="wait">
          {(activeItemIndex >= index || isComplete) && (
            <motion.li
              style={{
                width: '100%',
                justifyContent: 'flex-start',
                listStyle: 'none'
              }}
              initial="hidden"
              animate="visible"
              variants={itemVariants}
              onAnimationComplete={() => {
                if (activeItemIndex === index && itemAnimationIds[index]) {
                  // Complete this item's animation in the queue
                  completeAnimation(itemAnimationIds[index]);
                }
              }}
            >
              {child}
            </motion.li>
          )}
        </AnimatePresence>
      ))}
    </Component>
  );
};

export default AnimatedList;
